import requests
import time
import json
from memory_profiler import profile

@profile
def execute():
    post_url = "http://localhost:8002/score_image"
    results = []
    start_time = time.time()
    for i in range(1,4):
        id = str(i)
        payload = '''
        {
        "data": [
            {
                "id": %s,
                "bank": "Malaysia",
                "batchId": "1",
                "dateRef": "2021",
                "model_size": "base",
                "payeeName": "TS FORCE SDN. BHD.",
                "actions": [
                    "PAYEE_NAME_SCORING",
                    "LARCAR_SCORING",
                    "CAR_VALUE",
                    "DATE_VALIDATION"
                ],
                "mimeTypeImageFront": "image/tiff",
                "imageFront": ""
            }]
        }
        '''
        post_res = requests.post(post_url, data=payload % (id))
        if post_res.status_code == 200:
            results.append(post_res.text)

    #print(results)
    with open("./logs/result.json", "w") as f:
        json.dump(results, f, ensure_ascii=False, indent=4)

    end_time = time.time()
    print('*******************************************************************************************************************')
    print("Execution time for 4 calls: ", (end_time-start_time))
    print('*******************************************************************************************************************')

execute()




